```go
package cli

import "sync"

// IssueBackend is the backward-compatible interface for Phase 1 migration.
// It wraps raw bd-style command execution so callers don't change.
type IssueBackend interface {
    // RunCommand executes a bd-style command and returns stdout or error.
    // Example: RunCommand("ready", "--json", "--limit", "50")
    RunCommand(args ...string) (string, error)
}

// IssueTracker extends IssueBackend with typed methods for direct data access.
// Phase 2+ consumers should prefer these over RunCommand.
type IssueTracker interface {
    IssueBackend

    // Query operations
    Ready(opts ReadyOpts) ([]BdIssue, error)
    List(opts ListOpts) ([]BdIssue, error)
    Blocked() ([]BdIssue, error)
    Stats() (*BdStats, error)
    GetIssue(id string) (*BdIssue, error)
    GetIssueText(id string) (string, error)

    // Mutation operations
    UpdateStatus(id, status string) error
    UpdateExternalRef(id, ref string) error
    CloseIssue(id, reason string) error
    SyncStatus() error

    // Metadata
    BackendName() string
}

// ReadyOpts configures the Ready query.
type ReadyOpts struct {
    ParentID string // filter by parent epic ID (empty = no filter)
    Limit    int    // max results (0 = backend default)
}

// ListOpts configures the List query.
type ListOpts struct {
    Status   string // filter by status (empty = all)
    Assignee string // filter by assignee (empty = all)
    Type     string // filter by issue_type (empty = all)
    Limit    int    // max results (0 = backend default)
    JSON     bool   // request JSON output (used by RunCommand path)
}

// --- package-level tracker state ---

var (
    trackerMu   sync.RWMutex
    trackerInst IssueTracker
)

// defaultTracker returns the package-level IssueTracker.
// On first call, lazily initializes to a bdBackend wrapping the default BDRunner.
func defaultTracker() IssueTracker {
    trackerMu.RLock()
    t := trackerInst
    trackerMu.RUnlock()
    if t != nil {
        return t
    }
    // Lazy init: create default bdBackend
    trackerMu.Lock()
    defer trackerMu.Unlock()
    if trackerInst == nil {
        // TODO(loomcli-3p2t0.2): replace with newBdBackend(defaultDeps.BD, GetBeadsDir())
        // For now, leave nil — callers should check and fall back to direct bd calls
        // until bdBackend is implemented.
        trackerInst = nil
    }
    return trackerInst
}

// setDefaultTracker replaces the package-level IssueTracker.
// Used by config loading to switch backends, and by tests for injection.
func setDefaultTracker(t IssueTracker) {
    trackerMu.Lock()
    defer trackerMu.Unlock()
    trackerInst = t
}

// resetDefaultTracker clears the tracker for test isolation.
func resetDefaultTracker() {
    trackerMu.Lock()
    defer trackerMu.Unlock()
    trackerInst = nil
}
```

