  clearReviewed: () => void;
  /** Count of reviewed files out of total */
  reviewProgress: { reviewed: number; total: number };

  // Inline comments (localStorage)
  comments: InlineComment[];
  addComment: (filePath: string, lineNumber: number, content: string) => void;
  removeComment: (commentId: string) => void;
  /** Get comments for a specific file */
  getCommentsForFile: (filePath: string) => InlineComment[];

  // General
  refetch: () => Promise<void>;
}
