Interface:
```typescript
export interface UseEditorsResult {
  editors: EditorInfo[];
  detectedEditors: EditorInfo[];  // convenience: editors.filter(e => e.detected)
  isLoading: boolean;
  error: Error | null;
  refresh: () => Promise<void>;   // force re-fetch from backend
  openEditor: (editorId: string, path: string) => Promise<void>;
}
```

Implementation:
```typescript
export function useEditors(): UseEditorsResult {
  // Initialize from cache synchronously to avoid flash
  const [editors, setEditors] = useState<EditorInfo[]>(getCachedEditors() ?? []);
  const [isLoading, setIsLoading] = useState(getCachedEditors() === null);
  const [error, setError] = useState<Error | null>(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    // If cache is already populated, no need to fetch
    if (getCachedEditors() !== null) return;

    let cancelled = false;
    (async () => {
      try {
        const result = await fetchEditors();
        if (!cancelled && mountedRef.current) {
          setEditors(result);
          setError(null);
        }
      } catch (err) {
        if (!cancelled && mountedRef.current) {
          setError(err instanceof Error ? err : new Error(String(err)));
        }
      } finally {
        if (!cancelled && mountedRef.current) {
          setIsLoading(false);
        }
      }
    })();
    return () => { cancelled = true; mountedRef.current = false; };
  }, []);

  const refresh = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const result = await refreshEditors();
      if (mountedRef.current) {
        setEditors(result);
      }
    } catch (err) {
      if (mountedRef.current) {
        setError(err instanceof Error ? err : new Error(String(err)));
      }
    } finally {
      if (mountedRef.current) {
        setIsLoading(false);
      }
    }
  }, []);

  const openEditor = useCallback(async (editorId: string, path: string) => {
    await openInEditor(editorId, path);
  }, []);

  const detectedEditors = editors.filter(e => e.detected);

  return { editors, detectedEditors, isLoading, error, refresh, openEditor };
}
```

Key design choices:
- `getCachedEditors()` on init avoids an unnecessary loading state when cache is warm
- `detectedEditors` is a convenience filter — the downstream dropdown only shows detected editors
- `openEditor` wraps `openInEditor` so consumers don't need to import from the API layer
- No polling — editor list is stable (changes only when editors are installed/removed)

