### 1. `internal/webui/frontend/src/api/files.ts`

The main module. Structure:

```typescript
/**
 * API functions for agent worktree file operations.
 * Interfaces with GET/PUT /api/agents/{name}/files/* endpoints.
 */

import { get, ApiError, getAuthToken } from "./client";

// ============= Types =============

export interface FileEntry {
  name: string;
  is_dir: boolean;
  size: number;
  mod_time: string; // RFC3339
}

export interface DirListData {
  path: string;
  entries: FileEntry[];
}

export interface FileReadData {
  path: string;
  content?: string; // omitted when binary is true
  size: number;
  binary: boolean;
}

// ============= API Functions =============

/**
 * List files in an agent worktree directory (one level).
 * GET /api/agents/{name}/files/tree?path=
 */
export async function listWorktreeDir(
  agentName: string,
  path?: string,
): Promise<DirListData> {
  let url = `/api/agents/${encodeURIComponent(agentName)}/files/tree`;
  if (path !== undefined && path !== "") {
    url += `?path=${encodeURIComponent(path)}`;
  }
  return get<DirListData>(url);
}

/**
 * Read a file from an agent worktree.
 * GET /api/agents/{name}/files?path=
 */
export async function readWorktreeFile(
  agentName: string,
  path: string,
): Promise<FileReadData> {
  const url = `/api/agents/${encodeURIComponent(agentName)}/files?path=${encodeURIComponent(path)}`;
  return get<FileReadData>(url);
}

/**
 * Write a file to an agent worktree (atomic write).
 * PUT /api/agents/{name}/files?path=
 *
 * Uses raw fetch because client.ts does not export a put() helper.
 * Sends JSON body with {content: string} to match backend contract.
 */
export async function writeWorktreeFile(
  agentName: string,
  path: string,
  content: string,
): Promise<void> {
  const url = `/api/agents/${encodeURIComponent(agentName)}/files?path=${encodeURIComponent(path)}`;

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json",
  };
  const token = getAuthToken();
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  const response = await fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify({ content }),
  });

  if (!response.ok) {
    let body: string | undefined;
    try {
      body = await response.text();
    } catch {
      // ignore read errors
    }
    throw new ApiError(response.status, response.statusText, body);
  }
}
```

**Note on response pattern:** The read/list functions use `get<T>()` directly, returning the bare response type. This works because `client.ts` already throws `ApiError` for non-2xx HTTP responses. If the backend adds `{success, data}` wrappers at integration time, the call site would change to `get<ApiResult<DirListData>>(url)` with an `unwrap()` call — a trivial adjustment. Starting with the simpler bare-struct pattern avoids unnecessary complexity.

