export function FileExplorer() {
  const { agents } = useAgents({ pollInterval: 5000 });
  const [selectedAgent, setSelectedAgent] = useState<string>("");

  // Auto-select first agent when agents load
  useEffect(() => {
    if (agents.length > 0 && !selectedAgent) {
