import { useCallback } from "react";
import type { FileEntry } from "@/api/files";
import styles from "./FileExplorer.module.css";

interface FileTreeProps {
  treeData: Map<string, FileEntry[]>;
  expanded: Set<string>;
  selectedPath: string | null;
  filterText: string;
  onToggle: (dirPath: string) => Promise<void>;
  onSelectFile: (filePath: string | null) => void;
}

interface TreeNodeProps {
  entry: FileEntry;
  depth: number;
  treeData: Map<string, FileEntry[]>;
  expanded: Set<string>;
  selectedPath: string | null;
  filterText: string;
  onToggle: (dirPath: string) => Promise<void>;
  onSelectFile: (filePath: string | null) => void;
}

// Highlight matching text in name
function highlightMatch(name: string, filter: string): JSX.Element {
  if (!filter) return <>{name}</>;
  const lower = name.toLowerCase();
  const idx = lower.indexOf(filter.toLowerCase());
  if (idx === -1) return <>{name}</>;
  return (
    <>
      {name.slice(0, idx)}
      <mark className={styles.highlight}>{name.slice(idx, idx + filter.length)}</mark>
      {name.slice(idx + filter.length)}
    </>
  );
}

// Filter entries: show entry if it matches or any descendant matches
function shouldShow(
  entry: FileEntry,
  filter: string,
  treeData: Map<string, FileEntry[]>,
): boolean {
  if (!filter) return true;
  if (entry.name.toLowerCase().includes(filter.toLowerCase())) return true;
  if (entry.isDir) {
    const children = treeData.get(entry.path);
    if (children) {
      return children.some((child) => shouldShow(child, filter, treeData));
    }
  }
  return false;
}

function TreeNode({ entry, depth, treeData, expanded, selectedPath, filterText, onToggle, onSelectFile }: TreeNodeProps) {
  const isExpanded = expanded.has(entry.path);
  const isSelected = selectedPath === entry.path;
  const children = entry.isDir ? treeData.get(entry.path) : undefined;
  const indent = depth * 16;

  const handleClick = useCallback(() => {
    if (entry.isDir) {
      onToggle(entry.path);
    } else {
      onSelectFile(entry.path);
    }
  }, [entry, onToggle, onSelectFile]);

  return (
    <>
      <button
        type="button"
        className={styles.treeNode}
        style={{ paddingLeft: indent }}
        data-selected={isSelected || undefined}
        data-dir={entry.isDir || undefined}
        onClick={handleClick}
        aria-expanded={entry.isDir ? isExpanded : undefined}
        aria-label={entry.name}
      >
        {entry.isDir ? (
          <span className={`${styles.chevron} ${isExpanded ? styles.chevronExpanded : ""}`}>
            {/* Right-pointing triangle SVG */}
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M6 4l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="1.5" />
            </svg>
          </span>
        ) : (
          <span className={styles.fileIconSpacer} />
        )}
        <span className={styles.icon}>
          {entry.isDir ? (
            /* Folder SVG icon */
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M2 3h4l2 2h6v8H2V3z" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
            </svg>
          ) : (
            /* File SVG icon */
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M4 2h5l3 3v9H4V2z" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
              <path d="M9 2v3h3" fill="none" stroke="currentColor" strokeWidth="1.2" />
            </svg>
          )}
        </span>
        <span className={styles.fileName}>
          {highlightMatch(entry.name, filterText)}
        </span>
      </button>
      {entry.isDir && isExpanded && children && (
        children
          .filter((child) => shouldShow(child, filterText, treeData))
          .map((child) => (
            <TreeNode
              key={child.path}
              entry={child}
              depth={depth + 1}
              treeData={treeData}
              expanded={expanded}
              selectedPath={selectedPath}
              filterText={filterText}
              onToggle={onToggle}
              onSelectFile={onSelectFile}
            />
          ))
      )}
    </>
  );
}

export function FileTree({ treeData, expanded, selectedPath, filterText, onToggle, onSelectFile }: FileTreeProps) {
  const rootEntries = treeData.get("") ?? [];

  return (
    <div className={styles.tree} role="tree" aria-label="File tree">
      {rootEntries
        .filter((entry) => shouldShow(entry, filterText, treeData))
        .map((entry) => (
          <TreeNode
            key={entry.path}
            entry={entry}
            depth={0}
            treeData={treeData}
            expanded={expanded}
            selectedPath={selectedPath}
            filterText={filterText}
            onToggle={onToggle}
            onSelectFile={onSelectFile}
          />
        ))}
      {rootEntries.length === 0 && !filterText && (
        <div className={styles.empty}>No files found</div>
      )}
      {rootEntries.length > 0 && filterText && rootEntries.filter((e) => shouldShow(e, filterText, treeData)).length === 0 && (
        <div className={styles.empty}>No matches for &ldquo;{filterText}&rdquo;</div>
      )}
    </div>
  );
}
