d) Create `gatedHandleMutation` wrapper that checks source_repo against active filter:
```typescript
const sourceReposRef = useRef(sourceRepos);
useEffect(() => { sourceReposRef.current = sourceRepos; }, [sourceRepos]);

const gatedHandleMutation = useCallback((mutation: MutationPayload) => {
  const activeRepos = sourceReposRef.current;
  // If no filter is active (empty or undefined), allow all mutations
  if (!activeRepos || activeRepos.length === 0) {
    handleMutation(mutation);
    return;
  }
  // Allow mutations without source_repo (legacy/unknown origin)
  if (!mutation.source_repo) {
    handleMutation(mutation);
    return;
  }
  // Gate: only process mutations for selected repos
  if (activeRepos.includes(mutation.source_repo)) {
    handleMutation(mutation);
  } else if (process.env.NODE_ENV === "development") {
    console.debug(
      "[useIssues] Gated mutation for unselected repo:",
      mutation.source_repo,
      mutation.issue_id,
    );
  }
}, [handleMutation]);
```

e) Pass `gatedHandleMutation` to useSSE instead of `handleMutation`:
```typescript
const { ... } = useSSE({
  autoConnect,
  since: fetchTimestampRef.current > 0 ? fetchTimestampRef.current : undefined,
  onMutation: gatedHandleMutation,
  sourceRepos,
});
```

